// =============================================================================
// 参考插件：dual_ma —— 双均线交叉
// 迁移自 Rust 内建策略 crates/backtest/src/strategies.rs::DualMaStrategy（语义 1:1）。
// =============================================================================
//
// 评分映射口径（架构裁决，ADR §6/§13.1）：插件内部复刻 Rust 信号逻辑，
//   输出分数 Buy→80 / Sell→20 / Hold→50。等价性依据：默认聚合阈 60/40 下
//   80≥60 即聚合 Buy、20≤40 即聚合 Sell、50 居中即 Hold，
//   与 Rust 版 Signal::Buy/Sell/Hold 逐 bar 一一对应（守门测试：tests/equivalence.rs）。
//
// 仓位说明：不含 position_pct 参数——仓位换算是 ExecutionPolicy 职责
//   （ADR §13.1 决策/执行分层），插件只产评分；Rust 版 Signal::Buy(pct) 的 pct
//   在此映射为固定买入区高分 80。
//
// 语义注记（与 Rust 版逐条对齐）：
//   - 金叉定义：fast_ma > slow_ma 且上一有效 bar fast_ma <= slow_ma（严格大于）；
//     死叉反之。
//   - prev 状态仅当快/慢均线均可用（非 null）时更新；数据不足（指标 null）
//     → 中立分 50 且不更新 prev（对应 Rust 的 prev_above: Option<bool> 口径）。
//
// 内部状态（ABI G3）：prevAbove 模块级变量，经 save()/load() 快照/恢复。
// =============================================================================

const PARAMS_SCHEMA = [
  { key: "fast", type: "int", default: 5, min: 2, max: 200, description: "快线周期" },
  { key: "slow", type: "int", default: 20, min: 2, max: 250, description: "慢线周期" }
];

// 上一有效 bar 的「快线 > 慢线」状态；null = 尚无有效读数（对应 Rust None）。
let prevAbove = null;

function init(params) {
  prevAbove = null;
}

function on_bar(ctx) {
  const fast = ctx.indicators.ma(ctx.params.fast);
  const slow = ctx.indicators.ma(ctx.params.slow);
  if (fast === null || slow === null) {
    return 50; // 数据不足：中立，且不更新 prev
  }
  const above = fast > slow;
  let score = 50;
  if (prevAbove !== null) {
    if (above && !prevAbove) {
      score = 80; // 金叉 → Buy
    } else if (!above && prevAbove) {
      score = 20; // 死叉 → Sell
    }
  }
  prevAbove = above;
  return score;
}

function save() {
  return { prevAbove: prevAbove };
}

function load(state) {
  prevAbove = (state && (state.prevAbove === true || state.prevAbove === false))
    ? state.prevAbove
    : null;
}

// =============================================================================
// 参考插件：ma_rsi —— 均线交叉 + RSI 超买/超卖过滤
// 迁移自 Rust 内建策略 crates/backtest/src/strategies.rs::MaRsiStrategy（语义 1:1）。
// =============================================================================
//
// 评分映射口径（架构裁决，ADR §6/§13.1）：Buy→80 / Sell→20 / Hold→50。
//   等价性依据：默认聚合阈 60/40 下 80≥60 即 Buy、20≤40 即 Sell、50 即 Hold，
//   与 Rust 版 Signal 逐 bar 一一对应（守门测试：tests/equivalence.rs）。
//
// 仓位说明：不含 position_pct——仓位换算是 ExecutionPolicy 职责（ADR §13.1），
//   插件只产评分。
//
// 语义注记（与 Rust 版逐条对齐）：
//   - 金叉（快线上穿慢线）且 RSI < 超买线 → Buy；死叉且 RSI > 超卖线 → Sell。
//   - RSI 数据不足（null）按「通过」处理（对应 Rust 的 is_none_or / map_or(true)）。
//   - 快/慢均线任一不可用（null）→ 中立 50 且不更新 prev 状态。
//
// 内部状态（ABI G3）：prevAbove 模块级变量，经 save()/load() 快照/恢复。
// =============================================================================

const PARAMS_SCHEMA = [
  { key: "fast", type: "int", default: 5, min: 2, max: 200, description: "快线周期" },
  { key: "slow", type: "int", default: 20, min: 2, max: 250, description: "慢线周期" },
  { key: "rsi_period", type: "int", default: 14, min: 2, max: 60, description: "RSI 周期" },
  { key: "rsi_oversold", type: "float", default: 30, min: 10, max: 50, description: "RSI 超卖线" },
  { key: "rsi_overbought", type: "float", default: 70, min: 50, max: 90, description: "RSI 超买线" }
];

// 上一有效 bar 的「快线 > 慢线」状态；null = 尚无有效读数。
let prevAbove = null;

function init(params) {
  prevAbove = null;
}

function on_bar(ctx) {
  const fast = ctx.indicators.ma(ctx.params.fast);
  const slow = ctx.indicators.ma(ctx.params.slow);
  const rsi = ctx.indicators.rsi(ctx.params.rsi_period);
  if (fast === null || slow === null) {
    return 50; // 数据不足：中立，且不更新 prev
  }
  const above = fast > slow;
  let score = 50;
  if (prevAbove !== null) {
    if (above && !prevAbove) {
      // 金叉：RSI 未进入超买才 Buy；RSI 不足（null）按通过处理。
      if (rsi === null || rsi < ctx.params.rsi_overbought) {
        score = 80;
      }
    } else if (!above && prevAbove) {
      // 死叉：RSI 未进入超卖才 Sell；RSI 不足（null）按通过处理。
      if (rsi === null || rsi > ctx.params.rsi_oversold) {
        score = 20;
      }
    }
  }
  prevAbove = above;
  return score;
}

function save() {
  return { prevAbove: prevAbove };
}

function load(state) {
  prevAbove = (state && (state.prevAbove === true || state.prevAbove === false))
    ? state.prevAbove
    : null;
}

// =============================================================================
// 参考插件：macd —— MACD 金叉/死叉（DIF 上穿 DEA Buy / 下穿 Sell）
// 迁移自 Rust 内建策略 crates/backtest/src/strategies.rs::MacdStrategy（语义 1:1）。
// =============================================================================
//
// 评分映射口径（架构裁决，ADR §6/§13.1）：Buy→80 / Sell→20 / Hold→50。
//   等价性依据：默认聚合阈 60/40 下 80≥60 即 Buy、20≤40 即 Sell、50 即 Hold
//   （守门测试：tests/equivalence.rs）。
//
// 仓位说明：不含 position_pct——仓位换算是 ExecutionPolicy 职责（ADR §13.1）。
//
// 指标口径注记（重要）：
//   host 注入的 ctx.indicators.macd() 周期固定为 (12,26,9)（ABI §2），无法表达
//   本策略的 fast/slow/signal 参数。为与 Rust 版在任意参数下语义一致，本插件
//   按 backtest::Indicators::macd 口径**自持增量状态复算**：
//     - EMA 种子 = 首根 bar 的 close；DIF = EMA(fast) − EMA(slow)；
//     - DEA 种子 = 首根 DIF（= 0），之后按 signal 周期 EMA 递推；
//     - 全部 IEEE754 双精度同序运算，与 Rust 逐点一致（equivalence 测试含
//       默认参数 12/26/9 长序列抽查）。
//   前提：引擎从 bar 0 起逐 bar 连续调用 on_bar（EnsembleEngine 保证）。
//   MACD 自首根 bar 起即有值（Rust 版同样无暖机 null），故 prev 每 bar 更新。
//
// 内部状态（ABI G3）：emaFast/emaSlow/dea/seen/prevGt，经 save()/load() 快照/恢复。
// =============================================================================

const PARAMS_SCHEMA = [
  { key: "fast", type: "int", default: 12, min: 2, max: 100, description: "快线 EMA 周期" },
  { key: "slow", type: "int", default: 26, min: 2, max: 200, description: "慢线 EMA 周期" },
  { key: "signal", type: "int", default: 9, min: 2, max: 100, description: "信号线（DEA）周期" }
];

let emaFast = 0;
let emaSlow = 0;
let dea = 0;
let seen = 0;      // 已处理 bar 数（首根种子判定）
let prevGt = null; // 上一 bar 的 dif > dea；null = 尚无读数

function init(params) {
  emaFast = 0;
  emaSlow = 0;
  dea = 0;
  seen = 0;
  prevGt = null;
}

function on_bar(ctx) {
  const fast = ctx.params.fast;
  const slow = ctx.params.slow;
  const sig = ctx.params.signal;
  // 周期非法（Rust 版 fast/slow/signal 为 0 时指标 None → Hold 且不更新 prev）。
  if (fast < 1 || slow < 1 || sig < 1) {
    return 50;
  }
  const close = ctx.bar.close;
  if (seen === 0) {
    // 种子：EMA 双均线与 DEA 均以首根起算（DIF[0] = 0，DEA[0] = 0）。
    emaFast = close;
    emaSlow = close;
    dea = 0;
  } else {
    const kf = 2 / (fast + 1);
    const ks = 2 / (slow + 1);
    emaFast = close * kf + emaFast * (1 - kf);
    emaSlow = close * ks + emaSlow * (1 - ks);
    const ksig = 2 / (sig + 1);
    dea = (emaFast - emaSlow) * ksig + dea * (1 - ksig);
  }
  seen += 1;
  const dif = emaFast - emaSlow;
  const gt = dif > dea;
  let score = 50;
  if (prevGt !== null) {
    if (gt && !prevGt) {
      score = 80; // 金叉 → Buy
    } else if (!gt && prevGt) {
      score = 20; // 死叉 → Sell
    }
  }
  prevGt = gt;
  return score;
}

function save() {
  return { emaFast: emaFast, emaSlow: emaSlow, dea: dea, seen: seen, prevGt: prevGt };
}

// 防御口径（NIT-3）：与 dual_ma/boll 一致——字段缺失/类型错误时回退安全默认
// （= init() 初始值），不得将 undefined 写入状态引入 NaN 污染。
function load(state) {
  const s = state || {};
  emaFast = (typeof s.emaFast === "number") ? s.emaFast : 0;
  emaSlow = (typeof s.emaSlow === "number") ? s.emaSlow : 0;
  dea = (typeof s.dea === "number") ? s.dea : 0;
  seen = (typeof s.seen === "number") ? s.seen : 0;
  prevGt = (s.prevGt === true || s.prevGt === false) ? s.prevGt : null;
}

// =============================================================================
// 参考插件：boll —— BOLL 带突破（mean_reversion 默认 / trend 双模式）
// 迁移自 Rust 内建策略 crates/backtest/src/strategies.rs::BollStrategy（语义 1:1）。
// =============================================================================
//
// 评分映射口径（架构裁决，ADR §6/§13.1）：Buy→80 / Sell→20 / Hold→50。
//   等价性依据：默认聚合阈 60/40 下 80≥60 即 Buy、20≤40 即 Sell、50 即 Hold
//   （守门测试：tests/equivalence.rs）。
//
// 仓位说明：不含 position_pct——仓位换算是 ExecutionPolicy 职责（ADR §13.1）。
//
// 语义注记（与 Rust 版逐条对齐）：
//   - mode：mean_reversion（默认）= 收破下轨 Buy / 收破上轨 Sell（均值回归）；
//           trend = 收破上轨 Buy / 下破下轨 Sell（趋势突破）。
//   - 穿越判定：prev_close 相对**当前** band（上破：prev_close ≤ upper 且 close > upper；
//     下破：prev_close ≥ lower 且 close < lower），一次性信号。
//   - prev_close **无条件每 bar 记录**（含 band 不可用期间），确保 band 首次可用时
//     能检测到「越过 band」的一次性信号（Rust 同口径）。
//   - band 数据不足（boll 返回 null）→ 中立 50（仅记录 prev_close）。
//
// 参数编码注记：ABI §1 的 PARAMS_SCHEMA 仅支持 int/float，Rust 版的 Choice 参数
//   mode 在此编码为 int：0 = mean_reversion（默认）/ 1 = trend；缺省按 0 处理。
//
// 内部状态（ABI G3）：prevClose 模块级变量，经 save()/load() 快照/恢复。
// =============================================================================

const PARAMS_SCHEMA = [
  { key: "period", type: "int", default: 20, min: 2, max: 200, description: "周期" },
  { key: "k", type: "float", default: 2.0, min: 0.5, max: 4.0, description: "标准差倍数" },
  { key: "mode", type: "int", default: 0, min: 0, max: 1, description: "模式：0=mean_reversion（默认，均值回归）/ 1=trend（趋势突破）" }
];

// 上一 bar 收盘价；null = 首根之前（对应 Rust prev_close: Option<f64>）。
let prevClose = null;

function init(params) {
  prevClose = null;
}

function on_bar(ctx) {
  const close = ctx.bar.close;
  let score = 50;
  const b = ctx.indicators.boll(ctx.params.period, ctx.params.k);
  if (b !== null) {
    const crossedUp = prevClose !== null && prevClose <= b.upper && close > b.upper;
    const crossedDown = prevClose !== null && prevClose >= b.lower && close < b.lower;
    if (ctx.params.mode === 1) {
      // trend：收破上轨 Buy / 下破下轨 Sell。
      if (crossedUp) {
        score = 80;
      } else if (crossedDown) {
        score = 20;
      }
    } else {
      // mean_reversion（默认；mode 缺省/0）：收破下轨 Buy / 收破上轨 Sell。
      if (crossedDown) {
        score = 80;
      } else if (crossedUp) {
        score = 20;
      }
    }
  }
  prevClose = close; // 无条件记录（Rust 同口径）
  return score;
}

function save() {
  return { prevClose: prevClose };
}

function load(state) {
  prevClose = (state && typeof state.prevClose === "number") ? state.prevClose : null;
}

// =============================================================================
// 参考插件：kdj —— KDJ 金叉/死叉（K 上穿 D Buy / 下穿 Sell）
// 迁移自 Rust 内建策略 crates/backtest/src/strategies.rs::KdjStrategy（语义 1:1）。
// =============================================================================
//
// 评分映射口径（架构裁决，ADR §6/§13.1）：Buy→80 / Sell→20 / Hold→50。
//   等价性依据：默认聚合阈 60/40 下 80≥60 即 Buy、20≤40 即 Sell、50 即 Hold
//   （守门测试：tests/equivalence.rs）。
//
// 仓位说明：不含 position_pct——仓位换算是 ExecutionPolicy 职责（ADR §13.1）。
//
// 指标口径注记（重要）：
//   host 注入的 ctx.indicators.kdj() 周期固定为 (9,3,3)（ABI §2），无法表达
//   本策略的 n/k_period/d_period 参数。为与 Rust 版在任意参数下语义一致，
//   本插件按 backtest::Indicators::kdj 口径**自持滚动窗口与平滑状态复算**：
//     - RSV = (close − n周期最低low) / (n周期最高high − n周期最低low) × 100，
//       区间含当前 bar；high == low 时 RSV 取 50（Rust 同口径）；
//     - K/D 以 50 为种子，自窗口首次满 n 根起按 (m−1)/m 平滑递推；
//     - J = 3K − 2D（本策略只用 K/D 交叉，J 不参与判定）；
//     - 全部 IEEE754 双精度同序运算，与 Rust 逐点一致（equivalence 测试含
//       默认参数 9/3/3 长序列抽查）。
//   前提：引擎从 bar 0 起逐 bar 连续调用 on_bar（EnsembleEngine 保证）。
//   数据不足（窗口未满 n 根）→ 中立 50 且不更新 prev/K/D（对应 Rust kdj 返回 None
//   时 prev_k_gt_d 不更新的口径）。
//
// 内部状态（ABI G3）：highs/lows 滚动窗 + k/d/prevGt，经 save()/load() 快照/恢复。
// =============================================================================

const PARAMS_SCHEMA = [
  { key: "n", type: "int", default: 9, min: 2, max: 100, description: "RSV 周期" },
  { key: "k_period", type: "int", default: 3, min: 2, max: 30, description: "K 平滑周期" },
  { key: "d_period", type: "int", default: 3, min: 2, max: 30, description: "D 平滑周期" }
];

let highs = [];    // 最近 n 根 high（滚动窗）
let lows = [];     // 最近 n 根 low（滚动窗）
let k = 50;        // K 值（种子 50，Rust 同口径）
let d = 50;        // D 值（种子 50）
let prevGt = null; // 上一有效 bar 的 k > d；null = 尚无有效读数

function init(params) {
  highs = [];
  lows = [];
  k = 50;
  d = 50;
  prevGt = null;
}

function on_bar(ctx) {
  const n = ctx.params.n;
  const kp = ctx.params.k_period;
  const dp = ctx.params.d_period;
  if (n < 1 || kp < 1 || dp < 1) {
    return 50; // 周期非法（Rust 版指标 None → Hold）
  }
  highs.push(ctx.bar.high);
  lows.push(ctx.bar.low);
  if (highs.length > n) {
    highs.shift();
    lows.shift();
  }
  if (highs.length < n) {
    return 50; // 窗口未满：指标不可用 → 中立，不更新 prev/K/D
  }
  let hh = -Infinity;
  let ll = Infinity;
  for (let i = 0; i < highs.length; i++) {
    if (highs[i] > hh) { hh = highs[i]; }
    if (lows[i] < ll) { ll = lows[i]; }
  }
  const rsv = hh === ll ? 50 : (ctx.bar.close - ll) / (hh - ll) * 100;
  k = ((kp - 1) / kp) * k + (1 / kp) * rsv;
  d = ((dp - 1) / dp) * d + (1 / dp) * k;
  const gt = k > d;
  let score = 50;
  if (prevGt !== null) {
    if (gt && !prevGt) {
      score = 80; // 金叉 → Buy
    } else if (!gt && prevGt) {
      score = 20; // 死叉 → Sell
    }
  }
  prevGt = gt;
  return score;
}

function save() {
  return { highs: highs.slice(), lows: lows.slice(), k: k, d: d, prevGt: prevGt };
}

// 防御口径（NIT-3）：与 dual_ma/boll 一致——字段缺失/类型错误时回退安全默认
// （= init() 初始值），不得将 undefined 写入状态引入 NaN 污染。
function load(state) {
  const s = state || {};
  highs = Array.isArray(s.highs) ? s.highs.slice() : [];
  lows = Array.isArray(s.lows) ? s.lows.slice() : [];
  k = (typeof s.k === "number") ? s.k : 50;
  d = (typeof s.d === "number") ? s.d : 50;
  prevGt = (s.prevGt === true || s.prevGt === false) ? s.prevGt : null;
}

// =============================================================================
// 参考插件：momentum —— 动量突破（Donchian 通道）
// 迁移自 Rust 内建策略 crates/backtest/src/strategies.rs::MomentumStrategy（语义 1:1）。
// =============================================================================
//
// 评分映射口径（架构裁决，ADR §6/§13.1）：Buy→80 / Sell→20 / Hold→50。
//   等价性依据：默认聚合阈 60/40 下 80≥60 即 Buy、20≤40 即 Sell、50 即 Hold
//   （守门测试：tests/equivalence.rs）。
//
// 仓位说明：不含 position_pct——仓位换算是 ExecutionPolicy 职责（ADR §13.1）。
//
// 语义注记（与 Rust 版逐条对齐）：
//   - Donchian 上/下轨 = **当前 bar 之前** lookback 根 bar 的最高 high / 最低 low
//     （**不含当前 bar**，避免 close 恒 ≤ 当前 high 造成的自破位；Rust 模块头口径注记）；
//     无对应 host 指标，插件自持固定长度滚动窗口（与 Rust 的 VecDeque 一致）。
//   - 窗口未满 lookback 根 → 中立 50。
//   - close > 上轨 → Buy；close < 下轨 → Sell（即使空仓也发出 Sell 信号，
//     与 Rust 一致；是否成交由引擎按持仓决定）。
//   - 窗口在信号判定**之后**推入当前 bar（Rust 同序）。
//
// 内部状态（ABI G3）：highs/lows 滚动窗，经 save()/load() 快照/恢复。
// =============================================================================

const PARAMS_SCHEMA = [
  { key: "lookback", type: "int", default: 20, min: 2, max: 150, description: "回看日数" }
];

let highs = []; // 最近 lookback 根 high（不含当前 bar）
let lows = [];  // 最近 lookback 根 low（不含当前 bar）

function init(params) {
  highs = [];
  lows = [];
}

function on_bar(ctx) {
  const lb = ctx.params.lookback;
  let score = 50;
  if (highs.length === lb) {
    let hh = -Infinity;
    let ll = Infinity;
    for (let i = 0; i < highs.length; i++) {
      if (highs[i] > hh) { hh = highs[i]; }
      if (lows[i] < ll) { ll = lows[i]; }
    }
    if (ctx.bar.close > hh) {
      score = 80; // 突破上轨 → Buy
    } else if (ctx.bar.close < ll) {
      score = 20; // 跌破下轨 → Sell
    }
  }
  // 信号判定之后推入当前 bar（Rust 同序），窗口超长则弹出最旧一根。
  highs.push(ctx.bar.high);
  lows.push(ctx.bar.low);
  if (highs.length > lb) {
    highs.shift();
    lows.shift();
  }
  return score;
}

function save() {
  return { highs: highs.slice(), lows: lows.slice() };
}

// 防御口径（NIT-3）：与 dual_ma/boll 一致——字段缺失/类型错误时回退安全默认
// （= init() 初始值），不得将 undefined 写入状态引入 NaN 污染。
function load(state) {
  const s = state || {};
  highs = Array.isArray(s.highs) ? s.highs.slice() : [];
  lows = Array.isArray(s.lows) ? s.lows.slice() : [];
}

// =============================================================================
// 参考插件：atr_channel —— ATR 通道突破（Donchian 通道 + ATR 止损）
// 迁移自 Rust 内建策略 crates/backtest/src/strategies.rs::AtrChannelStrategy（语义 1:1）。
// =============================================================================
//
// 评分映射口径（架构裁决，ADR §6/§13.1）：Buy→80 / Sell→20 / Hold→50。
//   等价性依据：默认聚合阈 60/40 下 80≥60 即 Buy、20≤40 即 Sell、50 即 Hold
//   （守门测试：tests/equivalence.rs）。
//
// 仓位说明：不含 position_pct——仓位换算是 ExecutionPolicy 职责（ADR §13.1）。
//
// 语义注记（与 Rust 版逐条对齐）：
//   - Donchian 上/下轨 = **当前 bar 之前** channel_period 根 bar 的最高 high /
//     最低 low（**不含当前 bar**，Rust 模块头口径注记）；无对应 host 指标，
//     插件自持固定长度滚动窗口。
//   - 空仓判定用 ctx.position === null（对应 Rust 的 ctx.position > 0.0；
//     ABI §2.5：空仓时 host 给 null）。
//   - 空仓且 close 破上轨 → Buy，并记录 **entry = 自身 Buy 信号当根 close**
//     （插件内部状态记录，**不用 ctx.position.avg_cost**——口径注记：Rust 版
//     同样取信号 bar close 的近似值，实际成交在下一 open）。
//   - 持仓时 ATR 止损**优先**：close < entry − atr_multiplier × ATR(atr_period)
//     → Sell 并清空 entry；ATR 数据不足（null）→ 该 bar 不触发止损（Rust 同口径）。
//   - 止损未触发且 close 跌破通道下轨 → Sell（通道离场）并清空 entry。
//   - 窗口在信号判定**之后**推入当前 bar（Rust 同序）。
//
// 内部状态（ABI G3）：highs/lows 滚动窗 + entry，经 save()/load() 快照/恢复。
// =============================================================================

const PARAMS_SCHEMA = [
  { key: "channel_period", type: "int", default: 20, min: 2, max: 150, description: "通道周期" },
  { key: "atr_period", type: "int", default: 14, min: 2, max: 60, description: "ATR 周期" },
  { key: "atr_multiplier", type: "float", default: 1.0, min: 0.5, max: 5.0, description: "ATR 止损倍数" }
];

let highs = [];   // 最近 channel_period 根 high（不含当前 bar）
let lows = [];    // 最近 channel_period 根 low（不含当前 bar）
let entry = null; // 自身 Buy 信号当根 close（止损基准）；null = 无未平仓信号

function init(params) {
  highs = [];
  lows = [];
  entry = null;
}

function on_bar(ctx) {
  const cp = ctx.params.channel_period;
  const ready = highs.length === cp;
  let upper = -Infinity;
  let lower = Infinity;
  if (ready) {
    for (let i = 0; i < highs.length; i++) {
      if (highs[i] > upper) { upper = highs[i]; }
      if (lows[i] < lower) { lower = lows[i]; }
    }
  }

  let score = 50;
  const holding = ctx.position !== null;
  if (holding) {
    // ATR 止损优先（数据不足则不触发，Rust 同口径）。
    const a = ctx.indicators.atr(ctx.params.atr_period);
    if (a !== null && entry !== null &&
        ctx.bar.close < entry - ctx.params.atr_multiplier * a) {
      entry = null;
      score = 20;
    }
    // 通道下轨跌破 → 离场。
    if (score === 50 && ready && ctx.bar.close < lower) {
      entry = null;
      score = 20;
    }
  } else if (ready && ctx.bar.close > upper) {
    // 空仓 + 突破上轨 → Buy；entry 记当根 close（近似口径，见头注释）。
    entry = ctx.bar.close;
    score = 80;
  }

  // 信号判定之后推入当前 bar（Rust 同序），供下一根的通道计算。
  highs.push(ctx.bar.high);
  lows.push(ctx.bar.low);
  if (highs.length > cp) {
    highs.shift();
    lows.shift();
  }
  return score;
}

function save() {
  return { highs: highs.slice(), lows: lows.slice(), entry: entry };
}

// 防御口径（NIT-3）：与 dual_ma/boll 一致——字段缺失/类型错误时回退安全默认
// （= init() 初始值），不得将 undefined 写入状态引入 NaN 污染。
function load(state) {
  const s = state || {};
  highs = Array.isArray(s.highs) ? s.highs.slice() : [];
  lows = Array.isArray(s.lows) ? s.lows.slice() : [];
  entry = (typeof s.entry === "number") ? s.entry : null;
}

// =============================================================================
// 官方模板：pure_score —— 纯评分模板（ADR §13.2 D10 / ABI §4.5）
// =============================================================================
// 适用场景：最小编写起点。不读 ctx.position、无内部状态，只根据指标输出分数。
//
// 插件契约速览（权威：design/12-strategy-system/02-plugin-abi.md）：
//   - on_bar(ctx) 每 bar 调用一次，返回 0-100 连续分（越界由 host clamp）。
//   - 默认聚合阈值：总分 ≥ 60 → 买入信号；≤ 40 → 卖出信号；其余 → 持有。
//     所以「买入区」惯例给 80，「卖出区」惯例给 20，中立给 50。
//   - ctx.indicators 由 host 侧确定性计算（与 Rust 回测口径一致）；
//     数据不足返回 null，策略必须自行判空（否则 null 参与比较会得到意外结果）。
//   - ctx.params 为下方 PARAMS_SCHEMA 声明的参数（已由消费方填好默认值，只读冻结）。
//   - 插件只产评分，永远看不到订单/账户接口；仓位换算由 ExecutionPolicy 负责。
//
// 本模板策略：快均线上穿慢均线区间给 80（买入区），下穿区间给 20（卖出区），
// 数据不足给 50（中立）。无内部状态 → 无需实现 save()/load()。
// =============================================================================

const PARAMS_SCHEMA = [
  { key: "fast", type: "int", default: 5, min: 2, max: 200, description: "快线周期" },
  { key: "slow", type: "int", default: 20, min: 2, max: 250, description: "慢线周期" }
];

function on_bar(ctx) {
  const fast = ctx.indicators.ma(ctx.params.fast);
  const slow = ctx.indicators.ma(ctx.params.slow);
  // 数据不足（指标 null）→ 中立分：不表达观点。
  if (fast === null || slow === null) {
    return 50;
  }
  // 趋势上行 → 买入区高分；下行 → 卖出区低分。
  return fast > slow ? 80 : 20;
}

// =============================================================================
// 官方模板：two_state_gate —— 两态门控模板（ADR §13.2 D10 / ABI §4.5）
// =============================================================================
// 适用场景：只想「开一次仓、持有一段时间、条件变坏就离场」的策略。
// 核心手法（ABI §4.5）：空仓（ctx.position === null）时才给买入区高分；
// 持仓期给中立分——门控逻辑全部编码在「何时给多少分」里，引擎不做任何固定门控。
//
// ctx.position（ABI §2.5，只读持仓全景）：
//   null           → 当前空仓（纯评分试算模式下恒为 null）；
//   { qty, avg_cost, entry_ts, bars_since_entry, unrealized_pnl } → 持仓中。
// 注意：position 是共享组合视角的真实执行结果；插件修改它不会影响任何执行。
//
// 本模板策略：
//   空仓 + 快线 > 慢线 → 80（开门，允许买入）；
//   持仓 + 快线 < 慢线 → 20（趋势变坏，关门离场）；
//   其余 → 50（中立，不动作）。
// 无内部状态（门控完全由 ctx.position 驱动）→ 无需 save()/load()。
// =============================================================================

const PARAMS_SCHEMA = [
  { key: "fast", type: "int", default: 5, min: 2, max: 200, description: "快线周期" },
  { key: "slow", type: "int", default: 20, min: 2, max: 250, description: "慢线周期" }
];

function on_bar(ctx) {
  const fast = ctx.indicators.ma(ctx.params.fast);
  const slow = ctx.indicators.ma(ctx.params.slow);
  if (fast === null || slow === null) {
    return 50; // 数据不足 → 中立
  }
  const trendUp = fast > slow;
  if (ctx.position === null) {
    // 空仓：趋势向上才开门（买入区高分）。
    return trendUp ? 80 : 50;
  }
  // 持仓：趋势走坏给卖出区低分（离场），否则中立（继续持有）。
  return trendUp ? 50 : 20;
}

// =============================================================================
// 官方模板：dca —— 定投模板（ADR §13.2 D10 / ABI §4.5）
// =============================================================================
// 适用场景：分批建仓（定投式）。请配合 ExecutionPolicy = Dca（tranches/interval）
// 使用——**分批换算是 Policy 的职责**，插件只需控制「何时保持在买入区」。
//
// 与 DCA Policy 的协作口径（ADR §13.1）：
//   - Buy 信号（聚合 ≥ 60）持续期间，Policy 每 interval bar 执行一批，共 tranches 批；
//   - 信号中断（Hold/Sell）→ 剩余批次取消；Buy 重现 → 重新计数。
//   因此插件的典型写法：空仓且触发条件满足 → 给 80 开启本轮；随后用
//   ctx.position.bars_since_entry（建仓以来经过的 bar 数）控制高分持续的窗口，
//   窗口结束回到 50（中立），让 Policy 停止后续批次。
//
// 本模板策略：
//   空仓 + 收盘低于慢速均线（回踩）→ 80（开启一轮定投）；
//   持仓且 bars_since_entry < plan_bars → 继续 80（让 Policy 把批次打完）；
//   达到计划窗口 → 50（中立，停止加仓）；趋势深跌可改为 20 离场（留作练习）。
// 无内部状态（节奏由 ctx.position 驱动）→ 无需 save()/load()。
// =============================================================================

const PARAMS_SCHEMA = [
  { key: "slow", type: "int", default: 20, min: 2, max: 250, description: "慢线周期（回踩判定基准）" },
  { key: "plan_bars", type: "int", default: 3, min: 1, max: 60, description: "计划加仓窗口（bar 数，应与 DCA Policy 的 tranches×interval 对齐）" }
];

function on_bar(ctx) {
  const slow = ctx.indicators.ma(ctx.params.slow);
  if (slow === null) {
    return 50; // 数据不足 → 中立
  }
  if (ctx.position === null) {
    // 空仓：价格回踩慢线下方 → 开启一轮定投（买入区高分）。
    return ctx.bar.close < slow ? 80 : 50;
  }
  // 持仓：计划窗口内保持买入区高分（Policy 按 interval 逐批执行），窗口外中立。
  return ctx.position.bars_since_entry < ctx.params.plan_bars ? 80 : 50;
}

// =============================================================================
// 官方模板：trend_stop —— 趋势 + 止损模板（ADR §13.2 D10 / ABI §4.5）
// =============================================================================
// 适用场景：趋势跟随 + 软止损。演示三层止损中的「策略层（软止损）」（ADR §13.3）：
// 持仓亏损超过 stop_pct 时输出 0 分——强卖出区分数，把聚合总分拖过卖出阈。
//
// 软止损 vs 硬止损（重要口径）：
//   - 本模板的 0 分是**软止损**：它只是评分，可被执行层费用口径影响、
//     也可在组合回测中被其他策略的高分对冲（聚合是加权平均）。
//   - **硬止损**在 Run 级 stop 配置（fixed_pct/trailing/atr），触发即绕过评分
//     直接平仓，不依赖策略自觉。需要确定性保护时请用硬止损。
//
// 本模板策略：
//   持仓且 close < avg_cost × (1 − stop_pct) → 0（软止损，拖低总分至卖出区）；
//   快线 > 慢线 → 80（买入区）；快线 < 慢线 → 20（卖出区）；数据不足 → 50。
// 无内部状态 → 无需 save()/load()。
// =============================================================================

const PARAMS_SCHEMA = [
  { key: "fast", type: "int", default: 5, min: 2, max: 200, description: "快线周期" },
  { key: "slow", type: "int", default: 20, min: 2, max: 250, description: "慢线周期" },
  { key: "stop_pct", type: "float", default: 0.08, min: 0.01, max: 0.5, description: "软止损幅度（相对摊薄成本价，0.08 = 8%）" }
];

function on_bar(ctx) {
  // 软止损：持仓浮亏越线 → 0 分（强卖出区；单策略 60/40 阈下必然触发卖出信号）。
  if (ctx.position !== null &&
      ctx.bar.close < ctx.position.avg_cost * (1 - ctx.params.stop_pct)) {
    return 0;
  }
  const fast = ctx.indicators.ma(ctx.params.fast);
  const slow = ctx.indicators.ma(ctx.params.slow);
  if (fast === null || slow === null) {
    return 50; // 数据不足 → 中立
  }
  return fast > slow ? 80 : 20;
}

// =============================================================================
// dca_baseline —— 无脑定期定额（DCA Family #0：对照组，不是策略）
// 设计文档：design/01-dca-strategy-family.md §4.4
// =============================================================================
// 作用：**判断三个候选定投策略是否真有价值的唯一标尺。**
// 没有它，任何收益数字都无法解释——你不知道改善来自择时，还是来自市场本身。
//
// 逻辑：每 cadence 根 bar 到期投一期，窗口 plan_bars 内保持买入区，
//       不读任何指标、不做任何判断。
//
// 无内部状态（节奏由 ctx.index 算术导出）→ 无需 save()/load()。
// =============================================================================

const PARAMS_SCHEMA = [
  { key: "cadence", type: "int", default: 20, min: 1, max: 250, description: "定投周期（bar 数）" },
  { key: "plan_bars", type: "int", default: 5, min: 1, max: 120, description: "买入区保持窗口（bar 数）" }
];

function on_bar(ctx) {
  const p = ctx.params;
  const idx = ctx.index;
  const since = idx - Math.floor(idx / p.cadence) * p.cadence;
  return since < p.plan_bars ? 75 : 50;
}

// =============================================================================
// dca_ma_dev —— 均线偏离分档定投（DCA Family #1）
// 设计文档：design/01-dca-strategy-family.md §4.1
// =============================================================================
// 假设：收盘价相对长均线的负偏离，是"便宜"的廉价代理。跌得越深越买，
//       涨过均线就停投（但不卖）。
//
// 与 DCA Policy 的协作：本插件只决定"何时待在买入区"（≥60 分）；
// 实际分批由 ExecutionPolicy=Dca{tranches, interval} 执行。
// 一旦回到中立分（50/45），Policy 会取消本轮剩余批次。
//
// 不使用卖出区（≤40）：定投不做主动清仓，退出交给运行级硬止损。
//
// 内部状态：无（全部由当前 bar 与 ctx.position 决定）→ 无需 save()/load()。
// =============================================================================

const PARAMS_SCHEMA = [
  { key: "ma_n", type: "int", default: 60, min: 5, max: 250, description: "长均线周期（估值代理基准）" },
  { key: "dev_open", type: "float", default: 0.03, min: 0.005, max: 0.3, description: "开启一轮的负偏离阈值（0.03 = 低于均线 3%）" },
  { key: "dev_deep", type: "float", default: 0.08, min: 0.01, max: 0.5, description: "深度负偏离阈值（越低越买）" },
  { key: "stop_dev", type: "float", default: 0.02, min: 0.0, max: 0.5, description: "正偏离超过该值则本期不投（贵）" },
  { key: "plan_bars", type: "int", default: 10, min: 1, max: 120, description: "一轮买入区保持窗口（bar 数）" }
];

function on_bar(ctx) {
  const p = ctx.params;

  // 本轮批次还没投完 → 保持买入区，让 Policy 把 tranches 打完。
  if (ctx.position !== null && ctx.position.bars_since_entry < p.plan_bars) {
    return 80;
  }

  const ma = ctx.indicators.ma(p.ma_n);
  if (ma === null || ma <= 0) {
    return 50; // 冷启动数据不足 → 中立
  }

  const dev = ctx.bar.close / ma - 1;

  if (dev <= -p.dev_deep) return 85;    // 深度便宜：越跌越买
  if (dev <= -p.dev_open) return 75;    // 浅度便宜：开启新一轮
  if (dev > p.stop_dev) return 45;      // 贵：本期不投（观望，不触发卖出）
  return 50;                            // 均线附近：中立
}

// =============================================================================
// dca_drawdown —— 回撤触发定投（DCA Family #2）
// 设计文档：design/01-dca-strategy-family.md §4.2
// =============================================================================
// 假设：从近期高点回撤足够深，是比均线偏离更直接的风险释放信号。
//
// 通道 2 用法（手册 §4.5）：插件拿不到原始历史 bar 数组，需要滚动窗口时，
// 用模块级变量自持。**滚动状态必须进快照**，否则暂停/恢复/精确重放后行为分叉。
//
// 判定用"不含当前 bar"的窗口，避免当前 bar 恒等于自身 high 造成自破位。
//
// 不使用卖出区（≤40）：定投不做主动清仓，退出交给运行级硬止损。
// =============================================================================

const PARAMS_SCHEMA = [
  { key: "win", type: "int", default: 120, min: 5, max: 500, description: "回撤参考窗口（近 N 根最高价）" },
  { key: "dd_open", type: "float", default: 0.10, min: 0.01, max: 0.8, description: "触发开投的回撤幅度（0.10 = 距高点 -10%）" },
  { key: "dd_deep", type: "float", default: 0.20, min: 0.02, max: 0.9, description: "深度回撤阈值（越低越买）" },
  { key: "plan_bars", type: "int", default: 10, min: 1, max: 120, description: "一轮买入区保持窗口（bar 数）" }
];

// 滚动高点窗口（最近 win 根的 high，不含当前 bar 用于判定）
let highs = [];

function init(params) {
  highs = [];
}

function on_bar(ctx) {
  const p = ctx.params;

  // 1) 先用"不含当前 bar"的窗口算回撤
  let dd = 0;
  if (highs.length >= p.win) {
    let peak = -Infinity;
    const start = highs.length - p.win;
    for (let i = start; i < highs.length; i++) {
      if (highs[i] > peak) peak = highs[i];
    }
    if (peak > 0) dd = ctx.bar.close / peak - 1;
  }

  // 2) 判定
  let score = 50;
  if (ctx.position !== null && ctx.position.bars_since_entry < p.plan_bars) {
    score = 80;                                  // 本轮批次未投完
  } else if (dd <= -p.dd_deep) {
    score = 90;                                  // 深度回撤：越跌越买
  } else if (dd <= -p.dd_open) {
    score = 78;                                  // 回撤达标：开启新一轮
  }

  // 3) 判定之后再推窗（保证当前 bar 不参与本次判定）
  highs.push(ctx.bar.high);
  if (highs.length > p.win) highs.shift();

  return score;
}

function save() {
  return { highs: highs };
}

function load(state) {
  // 防御性恢复：快照可能损坏或被裁剪
  const src = (state && state.highs && state.highs.length !== undefined) ? state.highs : [];
  const out = [];
  for (let i = 0; i < src.length; i++) {
    const v = src[i];
    if (typeof v === "number" && isFinite(v)) out.push(v);
  }
  highs = out;
}

// =============================================================================
// dca_periodic —— 定期不定额（DCA Family #3）
// 设计文档：design/01-dca-strategy-family.md §4.3
// =============================================================================
// 假设：定投的纪律部分照做（按 cadence 到期就投），但只对"贵"做减法：
//       到期时 RSI 偏高 → 跳过本期；RSI 偏低 → 给高分并延长买入区窗口。
//
// 节奏完全由 ctx.index 算术导出，**无内部状态** → 无需 save()/load()，
// 也因此天然满足确定性与快照要求。
//
// 「不定额」的表达边界（设计文档 §2.1）：单批金额由 Policy 固定，插件改不了。
// 因此只能靠 (a) 跳过某些周期的批次、(b) 延长买入区窗口以消耗更多批次
// 来近似——tranches 耗尽后窗口不再有效。这是平台能力的真实边界。
//
// 不使用卖出区（≤40）：定投不做主动清仓，退出交给运行级硬止损。
// =============================================================================

const PARAMS_SCHEMA = [
  { key: "cadence", type: "int", default: 20, min: 1, max: 250, description: "定投周期（bar 数，到期投一期）" },
  { key: "plan_bars", type: "int", default: 5, min: 1, max: 120, description: "基础买入区窗口（bar 数）" },
  { key: "boost_bars", type: "int", default: 15, min: 1, max: 250, description: "超卖时的延长窗口（应 ≥ plan_bars）" },
  { key: "rsi_n", type: "int", default: 14, min: 2, max: 100, description: "RSI 周期" },
  { key: "rsi_skip", type: "float", default: 70, min: 50, max: 100, description: "RSI ≥ 该值则跳过本期（贵）" },
  { key: "rsi_boost", type: "float", default: 30, min: 0, max: 50, description: "RSI ≤ 该值则本期加倍投入" }
];

function on_bar(ctx) {
  const p = ctx.params;
  const idx = ctx.index;
  const since = idx - Math.floor(idx / p.cadence) * p.cadence; // 距上次到期的 bar 数

  // 1) 基础窗口内：保持买入区，让 Policy 把批次打完
  if (since < p.plan_bars) return 80;

  // 2) 超卖延长窗口：仍未到下一期且市场超卖 → 继续待在买入区
  if (since < p.boost_bars) {
    const r = ctx.indicators.rsi(p.rsi_n);
    if (r !== null && r <= p.rsi_boost) return 85;
  }

  // 3) 非到期日：中立
  if (since !== 0) return 50;

  // 4) 到期日：按估值决定投 / 跳过
  const rsi = ctx.indicators.rsi(p.rsi_n);
  if (rsi === null) return 75;             // 数据不足：按纪律照投
  if (rsi >= p.rsi_skip) return 45;        // 贵：跳过本期（观望，不触发卖出）
  if (rsi <= p.rsi_boost) return 88;       // 超卖：加倍
  return 75;                               // 正常投一期
}
